140	    public void dispose() {
141	        if (this.eventProcessingJob != null) {
142	            this.eventProcessingJob.cancel();
143	        }
144	        if (root != null) {
145	            this.root.dispose(false);
146	            synchronized (nodeMap) {
147	                this.nodeMap.clear();
148	            }
149	            this.root = null;
150	        }
151	        synchronized (this.listeners) {
152	            if (!listeners.isEmpty()) {
153	                for (INavigatorListener listener : listeners) {
154	                    log.warn("Listener '" + listener + "' is not unregistered from DBM model");
155	                }
156	            }
157	            this.listeners.clear();
158	            this.listenersCopy = null;
159	        }
