181	    @Nullable
182	    public DBNDatabaseNode getNodeByObject(@NotNull DBSObject object) {
183	        if (object instanceof DBNDatabaseNode) {
184	            return (DBNDatabaseNode)object;
185	        }
186	        object = DBUtils.getPublicObjectContainer(object);
187	
188	        Object obj;
189	        synchronized (nodeMap) {
190	            obj = nodeMap.get(object);
191	        }
192	        if (obj == null) {
193	            return null;
194	        } else if (obj instanceof DBNDatabaseNode dbNode) {
195	            return dbNode;
196	        } else if (obj instanceof List) {
197	            @SuppressWarnings("unchecked")
198	            List<DBNDatabaseNode> nodeList = (List<DBNDatabaseNode>) obj;
199	            if (nodeList.isEmpty()) {
200	                return null;

200	                return null;
201	            }
202	            if (nodeList.size() > 1) {
203	                for (DBNDatabaseNode node : nodeList) {
204	                    if (node instanceof DBNDatabaseItem && !node.getMeta().isVirtual()) {
205	                        return node;
206	                    }
207	                }
208	            }
209	            // Get just first one
210	            return nodeList.getFirst();
211	        } else {
212	            // Never be here
213	            throw new IllegalStateException();
214	        }
215	    }
216	
217	    @Nullable
218	    public DBNDatabaseNode getNodeByObject(@NotNull DBRProgressMonitor monitor, @Nullable DBSObject object, boolean addFiltered) {
219	        if (object instanceof DBSEntity entity) {
220	            try {
221	                object = DBVUtils.getRealEntity(monitor, entity);
222	            } catch (DBException e) {
223	                log.debug("Error dereferencing virtual entity", e);
224	            }
225	        }
226	        if (object == null) {
227	            return null;
228	        }
229	        DBNDatabaseNode node = getNodeByObject(object);
230	        if (node != null) {
231	            return node;
232	        }
233	        DBSObject[] path = DBUtils.getObjectPath(object, true);
234	        for (int i = 0; i < path.length - 1; i++) {
235	            DBSObject item = path[i];
236	            DBSObject nextItem = path[i + 1];
237	            node = getNodeByObject(item);
238	            if (node == null) {
239	                return null;
240	            }
241	            try {
242	                cacheNodeChildren(monitor, node, nextItem, addFiltered);
243	            } catch (DBException e) {
244	                log.error(e.getMessage());
245	                return null;
246	            }
247	        }
248	        return getNodeByObject(object);
249	    }
