251	    @NotNull
252	    private static NodePath getNodePath(@NotNull String path) {
253	        String prefix = DBNNode.NODE_URI_PREFIX;
254	        if (path.startsWith(prefix)) {
255	            path = path.substring(prefix.length());
256	        }
257	
258	        final List<String> items = CommonUtils.splitString(path, '/');
259	        items.replaceAll(DBNUtils::decodeNodePath);
260	        return new NodePath(items);
261	    }
