263	    @Nullable
264	    public DBNDataSource getDataSourceByPath(@NotNull DBPProject project, @NotNull String path) {
265	        DBNProject projectNode = getRoot().getProjectNode(project);
266	        if (projectNode == null) {
267	            return null;
268	        }
269	        NodePath nodePath = getNodePath(path);
270	        DBNProjectDatabases databaseRootNode = projectNode.getDatabases();
271	        int rootDbNodeIndex = nodePath.pathItems.indexOf(databaseRootNode.getNodeId());
272	        if (rootDbNodeIndex < 0) {
273	            return null;
274	        }
275	        Map<String, DBNDataSource> datasourceById = Arrays.stream(databaseRootNode.getDataSources())
276	            .collect(Collectors.toMap(DBNDataSource::getNodeId, Function.identity()));
277	        for (int i = rootDbNodeIndex + 1; i < nodePath.pathItems.size(); i++) {
278	            // it can be folder name or datasource id
279	            String potentialDatasourceId = nodePath.pathItems.get(i);
280	            if (datasourceById.containsKey(potentialDatasourceId)) {
281	                return datasourceById.get(potentialDatasourceId);
282	            }
283	        }
284	
285	        return null;
286	    }
