298	    /**
299	     * Converts a project-relative path to the full node path.
300	     *
301	     * @param project      Project to which the path is relative
302	     * @param relativePath Path relative to the project node, without path prefix.
303	     * @return Full node path with prefix, or {@code null} if the project node is not found or the path is not valid.
304	     */
305	    @Nullable
306	    public String toProjectPath(@NotNull DBPProject project, @NotNull String relativePath) {
307	        DBNProject projectNode = getRoot().getProjectNode(project);
308	        if (projectNode == null) {
309	            log.debug("Project node not found");
310	            return null;
311	        }
312	        NodePath path = getNodePath(relativePath);
313	        return projectNode.getNodeUri() + '/' + path.pathItems.stream()
314	            .map(DBNUtils::encodeNodePath)
315	            .collect(Collectors.joining("/"));
316	    }
