318	    @Nullable
319	    public DBNNode getNodeByPath(
320	        @NotNull DBRProgressMonitor monitor,
321	        @NotNull DBPProject project,
322	        @NotNull String path
323	    ) throws DBException {
324	        DBNProject projectNode = getRoot().getProjectNode(project);
325	        if (projectNode == null) {
326	            log.debug("Project node not found");
327	            return null;
328	        }
329	        NodePath nodePath = getNodePath(path);
330	       
331	        String projectNodePath = projectNode.getNodeUri();
332	        if (!path.startsWith(projectNodePath)) {
333	            throw new DBException("Node from another project");
334	        }
335	        int nodeLevel = getNodePath(projectNodePath).pathItems.size();
336	        return findNodeByPath(monitor, projectNode, nodePath, nodeLevel);
337	    }
338	
339	    @Nullable
340	    private DBNNode findNodeByPath(
341	        @NotNull DBRProgressMonitor monitor,
342	        @NotNull DBNNode currentNode,
343	        @NotNull NodePath nodePath,
344	        int currentLevel
345	    ) throws DBException {
346	        if (CommonUtils.isEmpty(nodePath.pathItems)) {
347	            return currentNode;
348	        }
349	        if (currentLevel >= nodePath.pathItems.size()) {
350	            throw new DBException("Node level " + currentLevel + " out of range: " + (nodePath.pathItems.size() - 1));
351	        }
352	        String expectedNodePathName = nodePath.pathItems.get(currentLevel);
353	        //skip fake root resource node
354	        //1 because project node is 0, fake resource node must be 1 in the path
355	        if (currentLevel == 1 && FAKE_RESOURCE_ROOT_NODE.equals(expectedNodePathName)) {
356	            currentLevel++;
357	            expectedNodePathName = nodePath.pathItems.get(currentLevel);
358	        }
359	        DBNNode[] children = currentNode.getChildren(monitor);
360	
361	        DBNNode detectedNode = null;
362	        for (DBNNode child : children) {
363	            if (child.getNodeId().equals(expectedNodePathName)) {
364	                detectedNode = child;
365	                break;
366	            }
367	        }
368	
369	        if (detectedNode == null) {
370	            log.debug("Node '" + expectedNodePathName + "' not found in parent node '"
371	                + currentNode.getNodeUri() + "'." + "\nAllowed children: " + Arrays.toString(children));
372	            return null;
373	        }
374	        if (detectedNode instanceof DBNNodeExtension nodeExtension) {
375	            detectedNode = nodeExtension.resolveRealNode();
376	            if (detectedNode == null) {
377	                log.error("Error resolving extension node for " + nodeExtension);
378	                return null;
379	            }
380	        }
381	
382	        if (currentLevel == nodePath.pathItems.size() - 1) {
383	            return detectedNode;
384	        } else {
385	            return findNodeByPath(monitor, detectedNode, nodePath, currentLevel + 1);
386	        }
387	    }
