390	    private boolean cacheNodeChildren(
391	        @NotNull DBRProgressMonitor monitor,
392	        @NotNull DBNDatabaseNode node,
393	        @NotNull DBSObject objectToCache,
394	        boolean addFiltered
395	    ) throws DBException {
396	        DBNDatabaseNode[] children = node.getChildren(monitor);
397	        boolean cached = false;
398	        if (!ArrayUtils.isEmpty(children)) {
399	            for (DBNDatabaseNode child : children) {
400	                if (child instanceof DBNDatabaseFolder) {
401	                    Class<?> itemsClass = ((DBNDatabaseFolder) child).getChildrenClass();
402	                    if (itemsClass != null && itemsClass.isAssignableFrom(objectToCache.getClass())) {
403	                        cached = cacheNodeChildren(monitor, child, objectToCache, addFiltered);
404	                        if (cached) {
405	                            break;
406	                        }
407	                    }
408	                } else if (child.getObject() == objectToCache) {
409	                    cached = true;
410	                    break;
411	                }
412	            }
413	        }
414	        if (!cached && addFiltered && node.isFiltered()) {
415	            // It seems this object was filtered out
416	            // As it was requested explicitly - let's add new node
417	            node.addChildItem(objectToCache);
418	            return true;
419	        }
420	        return false;
421	    }
