432	            }
433	        }
434	        DBSObject[] path = DBUtils.getObjectPath(object, false);
435	        DBSObject parentObject = object.getParentObject();
436	        if ((object instanceof DBSTablePartition part) && part.needFullPath()) {
437	            if (part.isSubPartition()) {
438	                parentObject = part.getPartitionParent();
439	            } else {
440	                parentObject = part.getParentTable();
441	            }
442	        }
443	        for (DBSObject item : path) {
444	            node = getNodeByObject(item);
445	            if (node == null) {
446	                // Parent node read
447	                return null;
448	            }
449	            DBNDatabaseNode[] children = node.getChildNodes();
450	            if (ArrayUtils.isEmpty(children)) {
451	                // Parent node is not read
452	                return null;
453	            }
454	
455	            if (item == DBUtils.getPublicObjectContainer(parentObject)) {
456	                // Try to find parent node withing children
457	                for (DBNDatabaseNode child : children) {
458	                    if (child instanceof DBNDatabaseFolder) {
459	                        Class<?> itemsClass = ((DBNDatabaseFolder) child).getChildrenClass();
460	                        if (itemsClass != null && itemsClass.isAssignableFrom(object.getClass())) {
461	                            return child;
462	                        }
463	                    }
464	                }
465	                // It is actual parent and there are no folders
466	                return node;
467	            }
468	        }
469	        // Not found
470	        return null;
471	    }
