478	    void addNode(@NotNull DBNDatabaseNode node, boolean reflect) {
479	        synchronized (nodeMap) {
480	            Object obj = nodeMap.get(node.getObject());
481	            if (obj == null) {
482	                // New node
483	                nodeMap.put(node.getObject(), node);
484	            } else if (obj instanceof DBNNode no) {
485	                // Second node - make a list
486	                List<DBNNode> nodeList = new ArrayList<>(2);
487	                nodeList.add(no);
488	                nodeList.add(node);
489	                nodeMap.put(node.getObject(), nodeList);
490	            } else if (obj instanceof List<?>) {
491	                // Multiple nodes
492	                @SuppressWarnings("unchecked")
493	                List<DBNNode> nodeList = (List<DBNNode>) obj;
494	                nodeList.add(node);
495	            }
496	        }
497	        if (reflect) {
498	            this.fireNodeEvent(new DBNEvent(this, DBNEvent.Action.ADD, DBNEvent.NodeChange.LOAD, node));
499	        }
500	    }
501	
502	    void removeNode(@NotNull DBNDatabaseNode node, boolean reflect) {
503	        boolean badNode = false;
504	        synchronized (nodeMap) {
505	            Object obj = nodeMap.get(node.getObject());
506	            if (obj == null) {
507	                // No found
508	                badNode = true;
509	            } else if (obj instanceof DBNNode) {
510	                // Just remove it
511	                if (nodeMap.remove(node.getObject()) != node) {
512	                    badNode = true;
513	                }
514	            } else if (obj instanceof List) {
515	                // Multiple nodes
516	                @SuppressWarnings("unchecked")
517	                List<DBNNode> nodeList = (List<DBNNode>) obj;
518	                if (!nodeList.remove(node)) {
519	                    badNode = true;
520	                }
521	                if (nodeList.isEmpty()) {
522	                    nodeMap.remove(node.getObject());
523	                }
524	            }
525	        }
526	        if (badNode) {
527	            log.warn("Remove unregistered meta node object " + node.getNodeDisplayName());
528	        } else {
529	            if (reflect) {
530	                this.fireNodeEvent(new DBNEvent(this, DBNEvent.Action.REMOVE, DBNEvent.NodeChange.UNLOAD, node));
531	            }
532	        }
533	    }
