618	    private class EventProcessingJob extends Job {
619	
620	        EventProcessingJob() {
621	            super("Navigator notifier");
622	            setSystem(true);
623	        }
624	
625	        @Override
626	        protected IStatus run(IProgressMonitor monitor) {
627	            Thread.currentThread().setName("Database navigator events processor");
628	            while (!platform.isShuttingDown()) {
629	                RuntimeUtils.pause(100);
630	                final INavigatorListener[] realListeners;
631	                synchronized (listeners) {
632	                    realListeners = listenersCopy;
633	                }
634	                if (realListeners == null || realListeners.length == 0) {
635	                    continue;
636	                }
637	                final DBNEvent[] realEvents;
638	                synchronized (eventCache) {
639	                    if (eventCache.isEmpty()) {
640	                        continue;
641	                    }
642	                    realEvents = eventCache.toArray(new DBNEvent[0]);
643	                    eventCache.clear();
644	                }
645	
646	                try {
647	                    DBWorkbench.getPlatformUI().executeInMainThread(() -> {
648	                        for (int i = 0; i < realEvents.length; i++) {
649	                            for (INavigatorListener listener : listenersCopy) {
650	                                listener.nodeChanged(realEvents[i]);
651	                            }
652	                        }
653	                    });
654	                } catch (Exception e) {
655	                    log.error(e);
656	                }
657	            }
658	            return Status.OK_STATUS;
659	        }
660	    }
