339	     * Refreshes node.
340	     * If refresh cannot be done in this level then refreshes parent node.
341	     * Do not actually changes navigation tree. If some underlying object is refreshed it must fire DB model
342	     * event which will cause actual tree nodes refresh. Underlying object could present multiple times in
343	     * navigation model - each occurrence will be refreshed then.
344	     *
345	     * @param monitor progress monitor
346	     * @param source  source object
347	     * @return real refreshed node or null if nothing was refreshed
348	     * @throws DBException on any internal exception
349	     */
350	    @Nullable
351	    @Override
352	    public DBNNode refreshNode(@NotNull DBRProgressMonitor monitor, @Nullable Object source) throws DBException {
353	        if (isLocked()) {
354	            log.warn("Attempt to refresh locked node '" + getNodeDisplayName() + "'"); //$NON-NLS-1$ //$NON-NLS-2$
355	            return null;
356	        }
357	        DBSObject object = getObject();
358	        if (object instanceof DBPRefreshableObject refreshableObject) {
359	            DBPDataSource dataSource = object.getDataSource();
360	            if (object.isPersisted() && dataSource != null) {
361	                DBSObject[] newObject = new DBSObject[1];
362	                DBExecUtils.tryExecuteRecover(monitor, dataSource, param ->
363	                    newObject[0] = refreshableObject.refreshObject(monitor));
364	                if (newObject[0] == null) {
365	                    if (parentNode instanceof DBNDatabaseNode dbNode) {
366	                        dbNode.removeChildItem(object);
367	                    }
368	                    return null;
369	                } else {
370	                    refreshNodeContent(monitor, newObject[0], source, true);
371	                    return this;
372	                }
373	            } else {
374	                // Not persisted node - nothing to refresh
375	                getModel().fireNodeUpdate(source, this, DBNEvent.NodeChange.REFRESH);
376	                return this;
377	            }
378	        } else {
379	            return super.refreshNode(monitor, source);
380	        }
381	    }
