383	    private void refreshNodeContent(final DBRProgressMonitor monitor, DBSObject newObject, Object source, boolean reflect)
384	    throws DBException {
385	        if (isDisposed()) {
386	            return;
387	        }
388	        this.locked = true;
389	        DBNModel model = getModel();
390	        try {
391	            if (newObject != getObject()) {
392	                reloadObject(monitor, newObject);
393	            }
394	
395	            this.reloadChildren(monitor, source, reflect);
396	
397	            if (reflect) model.fireNodeUpdate(source, this, DBNEvent.NodeChange.REFRESH);
398	        } finally {
399	            this.locked = false;
400	        }
401	    }
