419	        final DBNDatabaseNode[] oldList,
420	        final List<DBNDatabaseNode> toList,
421	        Object source,
422	        boolean reflect
423	    ) throws DBException {
424	        if (monitor.isCanceled()) {
425	            return;
426	        }
427	
428	        List<DBXTreeNode> childMetas = meta.getChildren(this);
429	        if (CommonUtils.isEmpty(childMetas)) {
430	            // Get top-most parent node
431	            if (!isDynamicStructObject()) {
432	                return;
433	            }
434	            DBNDatabaseDynamicItem[] dsc = getDynamicStructChildren();
435	            if (dsc == null) {
436	                return;
437	            }
438	            Collections.addAll(toList, dsc);
439	            return;
440	        }
441	        DBSObject object = getObject();
442	        if (object == null) {
443	            // disposed?
444	            return;
445	        }
446	        DBPDataSourceContainer container = getDataSourceContainer();
447	        DBNBrowseSettings navSettings = container.getNavigatorSettings();
448	        final boolean showSystem = navSettings.isShowSystemObjects();
449	        final boolean showOnlyEntities = navSettings.isShowOnlyEntities();
450	        final boolean hideFolders = navSettings.isHideFolders();
451	        boolean mergeEntities = navSettings.isMergeEntities();
452	        boolean supportsOptionalFolders = false;
453	        DBPDataSource dataSource = container.getDataSource();
454	        if (dataSource instanceof DBPDataSourceWithOptionalElements swoe) {
455	            supportsOptionalFolders = swoe.hasOptionalFolders();
456	        }
457	
458	        for (DBXTreeNode child : childMetas) {
459	            if (monitor.isCanceled()) {
460	                break;
461	            }
462	            if (showOnlyEntities && !isEntityMeta(child)) {
463	                continue;
464	            }
465	
466	            if (child instanceof DBXTreeItem item) {
467	                /*if (hideSchemas && isSchemaItem(item)) {
468	                    // Merge
469	                } else */{
470	                    boolean isLoaded = loadTreeItems(monitor, item, oldList, toList, source, showSystem, hideFolders, mergeEntities, reflect);
471	                    if (!isLoaded && item.isOptional() && item.getRecursiveLink() == null) {
472	                        // This may occur only if no child nodes was read
473	                        // Then we try to go on next DBX level
474	                        loadChildren(monitor, item, oldList, toList, source, reflect);
475	                    }
476	                }
477	            } else if (child instanceof DBXTreeFolder treeFolder) {
478	                if (hideFolders || ((mergeEntities || supportsOptionalFolders) && treeFolder.isOptional())) {
479	                    if (child.isVirtual() || treeFolder.isAdminFolder()) {
480	                        continue;
481	                    }
482	                    // Fall down
483	                    loadChildren(monitor, child, oldList, toList, source, reflect);
484	                } else {
485	                    String optionalPath = treeFolder.getOptionalItem();
486	                    if (optionalPath != null) {
487	                        DBXTreeItem optionalItem = treeFolder.getChildByPath(optionalPath);
488	                        if (optionalItem == null) {
489	                            log.error("Optional item '" + optionalPath + "' not found in folder " + child.getId());
490	                        } else {
491	                            Object optionalValue = extractPropertyValue(monitor, getValueObject(), optionalItem);
492	                            if (optionalValue == null || (optionalValue instanceof Collection<?> col && col.isEmpty())) {
493	                                // Go on next DBX level
494	                                loadChildren(monitor, optionalItem, oldList, toList, source, reflect);
495	                                continue;
496	                            }
497	                        }
498	                    }
499	
500	                    if (oldList == null) {
501	                        // Load new folders only if there are no old ones
502	                        toList.add(
503	                            new DBNDatabaseFolder(this, (DBXTreeFolder) child));
504	                    } else {
505	                        for (DBNDatabaseNode oldFolder : oldList) {
506	                            if (oldFolder.getMeta() == child) {
507	                                oldFolder.reloadChildren(monitor, source, reflect);
508	                                toList.add(oldFolder);
509	                                break;
510	                            }
511	                        }
512	                    }
513	                }
514	            } else if (child instanceof DBXTreeObject treeObject) {
515	                if (hideFolders) {
516	                    continue;
517	                }
518	                if (oldList == null) {
519	                    // Load new objects only if there are no old ones
520	                    toList.add(
521	                        new DBNDatabaseObject(this, treeObject));
522	                } else {
523	                    for (DBNDatabaseNode oldObject : oldList) {
524	                        if (oldObject.getMeta().equals(child)) {
525	                            oldObject.reloadChildren(monitor, source, reflect);
526	                            toList.add(oldObject);
527	                            break;
528	                        }
529	                    }
530	                }
531	            } else {
532	                log.warn("Unsupported meta node type: " + child); //$NON-NLS-1$
533	            }
534	        }
535	
536	        if (reflect && filtered) {
537	            getModel().fireNodeUpdate(this, this, DBNEvent.NodeChange.REFRESH);
538	        }
539	    }
